  <script>
    // Program opener (fills checklist and info)
    function openProgram(title,duration,desc){
      const txt = title + ' — ' + duration + '\n' + desc + '\n\nUse the checklist to try for 7 days.';
      alert(txt);
    }

    // Program session planner
    function makeProgramPlan(focus,length,count){
      return 'Program session template:\nFocus: '+focus+'\nLength: '+length+' minutes\nReps/Blocks: '+count+'\nTips: Add a 2-minute check-in and 2-minute reflection.';
    }
    document.getElementById('prog_build').addEventListener('click', function(){
      const f = document.getElementById('prog_focus').value || 'General';
      const l = document.getElementById('prog_length').value;
      const c = document.getElementById('prog_count').value;
      document.getElementById('prog_out').textContent = makeProgramPlan(f,l,c);
    });
    document.getElementById('prog_copy').addEventListener('click', function(){
      const txt = document.getElementById('prog_out').textContent;
      if(!txt){alert('Create the plan first.');return}
      navigator.clipboard && navigator.clipboard.writeText(txt).then(()=>alert('Template copied.'),()=>alert('Copy failed'));
    });

    // Checklist generator
    function formatDate(date){
      return date.toISOString().slice(0,10);
    }
    document.getElementById('makeChecklist').addEventListener('click', function(){
      const prog = document.getElementById('selectProg').value;
      const startVal = document.getElementById('startDate').value;
      const start = startVal ? new Date(startVal) : new Date();
      let lines = '7-day checklist for: '+prog+'\nStart: '+formatDate(start)+'\n\n';
      for(let i=0;i<7;i++){
        const d = new Date(start.getTime()); d.setDate(start.getDate()+i);
        lines += (i+1)+'. '+d.toDateString()+' — [  ]\n';
      }
      document.getElementById('checkArea').textContent = lines;
    });
    document.getElementById('printChecklist').addEventListener('click', function(){
      const txt = document.getElementById('checkArea').textContent || 'No checklist yet.';
      const win = window.open('about:blank','print');
      win.document.write('<pre style="font-family:system-ui;white-space:pre-wrap">'+txt.replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</pre>');
      win.document.close();
      setTimeout(()=>win.print(),250);
    });
  </script>
